frost:{slots:['armor','crown','leggings'],enhance:2,stars:2,stone:28,shard:7,gem:2,essence:6},
honey:{slots:['bracers','amulet','spiritguard'],enhance:2,stars:2,stone:32,shard:8,gem:2,essence:7},
