const IDS=['d0','d1','d2','d3','w0','w1','w2','w3'],GEAR_IDS=['bow','crown','armor','boots','ring','charm'];
function valid(s){return s&&s.version===1&&(s.valeChapter===undefined||Number.isInteger(s.valeChapter)&&s.valeChapter>=0&&s.valeChapter<4)&&['gold','tickets','scales','xp','rolls','guarantees','defenseWins','mergeBest','revision','updated'].every(k=>Number.isSafeInteger(s[k])&&s[k]>=0&&s[k]<=(k==='updated'?1e15:1e12))&&['dungeonWins','sparWins'].every(k=>s[k]===undefined||Number.isSafeInteger(s[k])&&s[k]>=0&&s[k]<=1e12)&&globalThis.WonderProgress.validDaily(s.expDungeon)&&globalThis.WonderAdventure.valid(s.adventure)&&globalThis.WonderGear.valid(s.equipment)&&typeof s.name==='string'&&s.name.trim().length>0&&s.name.length<=24&&Array.isArray(s.owned)&&s.owned.length<=8&&new Set(s.owned).size===s.owned.length&&s.owned.includes('d0')&&s.owned.includes('w0')&&s.owned.every(id=>IDS.includes(id))&&s.owned.includes(s.dragon)&&s.dragon[0]==='d'&&s.owned.includes(s.wings)&&s.wings[0]==='w'&&Array.isArray(s.claimed)&&s.claimed.length<=5&&s.claimed.every(n=>[15,30,60,135,240].includes(n))&&GEAR_IDS.every(g=>Number.isInteger(s.upgrades?.[g])&&s.upgrades[g]>=0&&s.upgrades[g]<=20)}
function power(s){const st=globalThis.WonderGear.stats(s);return {power:st.power,level:st.level}}
function json(data,status=200){return Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}
export default {async fetch(request,env){const url=new URL(request.url);try{if(url.pathname.startsWith('/api/')){const uid=request.headers.get('oai-authenticated-user-id');if(!uid)return json({error:'Sign in to save your adventure.'},401);if(!env.DB)return json({error:'Cloud is not configured.'},503);if(!['GET','HEAD'].includes(request.method)){const origin=request.headers.get('Origin');if(origin&&origin!==url.origin)return json({error:'Invalid origin'},403);const contentType=request.headers.get('Content-Type')||'';if(!contentType.startsWith('application/json'))return json({error:'JSON required'},415)}
if(url.pathname==='/api/save'&&request.method==='GET'){const row=await env.DB.prepare('SELECT save_json, revision FROM adventures WHERE user_id = ?').bind(uid).first();return json(row?{save:JSON.parse(row.save_json),revision:row.revision}:{save:null,revision:0})}
if(url.pathname==='/api/save'&&request.method==='PUT'){const text=await request.text();if(text.length>30000)return json({error:'Save too large'},413);let body;try{body=JSON.parse(text)}catch{return json({error:'Invalid JSON'},400)}if(!valid(body.save)||!Number.isSafeInteger(body.revision)||body.revision<0)return json({error:'Invalid save'},400);const s=body.save,revision=body.revision,st=power(s);s.revision=revision+1;s.name=s.name.trim();let result;if(revision===0){result=await env.DB.prepare('INSERT INTO adventures (user_id,save_json,revision,updated_at,hero_name,power,level) VALUES (?,?,1,?,?,?,?) ON CONFLICT(user_id) DO NOTHING').bind(uid,JSON.stringify(s),Date.now(),s.name,st.power,st.level).run()}else{result=await env.DB.prepare('UPDATE adventures SET save_json=?,revision=revision+1,updated_at=?,hero_name=?,power=?,level=? WHERE user_id=? AND revision=?').bind(JSON.stringify(s),Date.now(),s.name,st.power,st.level,uid,revision).run()}if(result.meta.changes!==1)return json({error:'Save conflict'},409);return json({revision:revision+1})}
if(url.pathname==='/api/leaderboard'&&request.method==='GET'){const entries=await env.DB.prepare('SELECT hero_name AS name,power,level,CASE WHEN user_id=? THEN 1 ELSE 0 END AS isSelf FROM adventures WHERE shared=1 ORDER BY power DESC LIMIT 20').bind(uid).all();return json({entries:entries.results})}
if(url.pathname==='/api/leaderboard'&&request.method==='POST'){const r=await env.DB.prepare('UPDATE adventures SET shared=1 WHERE user_id=?').bind(uid).run();if(!r.meta.changes)return json({error:'Save your adventure first'},409);return json({shared:true})}return json({error:'Not found'},404)}
const path=url.pathname==='/'?'/index.html':url.pathname;const asset=ASSETS[path];if(!asset)return new Response('Not found',{status:404});const headers={'Content-Type':asset.type,'X-Content-Type-Options':'nosniff','Cache-Control':path.endsWith('.webp')?'public,max-age=86400':'no-cache'};if(request.method==='HEAD')return new Response(null,{headers});if(request.method!=='GET')return new Response('Method not allowed',{status:405});return new Response(asset.base64?Uint8Array.from(atob(asset.content),c=>c.charCodeAt(0)):asset.content,{headers});}catch(e){return json({error:'The cloud is temporarily unavailable. Your device save is safe.'},503)}}};
